    #[cfg(unix)]
    #[test]
    fn sops_rename_reports_a_filesystem_failure_as_a_server_error() {
        // A well-formed request against a manifest the daemon cannot read is
        // the daemon's problem, not the caller's: it must not come back as
        // INVALID_PARAMS, which tells the client to fix its input.
        use std::os::unix::fs::PermissionsExt;

        let tmp = tempfile::TempDir::new().unwrap();
        let sops_dir = tmp.path().join("sops");
        crate::sop::save_sop(&sops_dir, &author_test_sop("rpc-unreadable")).unwrap();
        let manifest = sops_dir.join("rpc-unreadable").join("SOP.toml");
        let original = std::fs::metadata(&manifest).unwrap().permissions();
        std::fs::set_permissions(&manifest, std::fs::Permissions::from_mode(0o000)).unwrap();
        if std::fs::read_to_string(&manifest).is_ok() {
            // Running as root, where the mode bits above are advisory.
            std::fs::set_permissions(&manifest, original).unwrap();
            return;
        }

        let (d, _rx) = make_sop_author_dispatcher(tmp.path());
        let err = d
            .handle_sops_rename(
                &serde_json::json!({ "from": "rpc-unreadable", "to": "rpc-readable" }),
            )
            .expect_err("an unreadable manifest must fail the rename");
        std::fs::set_permissions(&manifest, original).unwrap();

        assert_eq!(err.code, INTERNAL_ERROR, "{err:?}");
    }

    #[test]
    fn sops_save_still_refuses_to_rename_the_sop_it_is_editing() {
        // Edit identity: `sops/save` persists under the submitted SOP's own
        // name, so a name change slipped through a save would fork the SOP or
        // clobber another. Renaming has its own method; save keeps rejecting.
        let tmp = tempfile::TempDir::new().unwrap();
        let sops_dir = tmp.path().join("sops");
        crate::sop::save_sop(&sops_dir, &author_test_sop("rpc-editing")).unwrap();
        let (d, _rx) = make_sop_author_dispatcher(tmp.path());

        let err = d
            .handle_sops_save(&serde_json::json!({
                "sop": serde_json::to_value(author_test_sop("rpc-renamed-by-save")).unwrap(),
                "original_name": "rpc-editing",
            }))
            .expect_err("an edit-save may not change the SOP's name");
        assert_eq!(err.code, INVALID_PARAMS);
        assert!(err.message.contains("rename not supported"), "{err:?}");
        assert!(sops_dir.join("rpc-editing").exists());
        assert!(
            !sops_dir.join("rpc-renamed-by-save").exists(),
            "a rejected edit-save writes nothing at all"
        );
    }

    fn make_checkpoint_rpc_dispatcher(
        quorum: u32,
        members: &[&str],
        tui_id: &str,
    ) -> (
        RpcDispatcher,
        Arc<std::sync::Mutex<crate::sop::SopEngine>>,
        String,
        tempfile::TempDir,
    ) {
        use crate::sop::types::{
            Sop, SopAdmissionPolicy, SopEvent, SopExecutionMode, SopPriority, SopRunAction,
            SopStep, SopStepKind, SopTrigger, SopTriggerSource,
        };
        use std::collections::HashMap;
        use zeroclaw_config::schema::{
            ApprovalGroupConfig, ApprovalPolicyConfig, Config, SopApprovalConfig,
        };
        use zeroclaw_infra::session_queue::SessionActorQueue;

        let temp = tempfile::TempDir::new().unwrap();
        let sops_dir = temp.path().join("sops");
        let sop = Sop {
            name: "rpc-checkpoint".into(),
            description: "checkpoint RPC authorization test".into(),
            version: "1.0.0".into(),
            priority: SopPriority::Normal,
            execution_mode: SopExecutionMode::Deterministic,
            triggers: vec![SopTrigger::Manual],
            steps: vec![
                SopStep {
                    number: 1,
                    title: "authorize".into(),
                    kind: SopStepKind::Checkpoint,
                    policy: Some("prod".into()),
                    ..SopStep::default()
                },
                SopStep {
                    number: 2,
                    title: "continue".into(),
                    kind: SopStepKind::Execute,
                    ..SopStep::default()
                },
            ],
            cooldown_secs: 0,
            max_concurrent: 1,
            location: None,
            deterministic: false,
            admission_policy: SopAdmissionPolicy::Parallel,
            max_pending_approvals: 0,
            agent: None,
            decision: None,
        };
        crate::sop::save_sop(&sops_dir, &sop).unwrap();
        let mut groups = HashMap::new();
        groups.insert(
            "release".to_string(),
            ApprovalGroupConfig {
                members: members.iter().map(|member| (*member).to_string()).collect(),
            },
        );
        let mut policies = HashMap::new();
        policies.insert(
            "prod".to_string(),
            ApprovalPolicyConfig {
                required_group: Some("release".into()),
                quorum,
                request_route: None,
                escalation_route: None,
            },
        );
        let mut config = Config::default();
        config.sop.sops_dir = Some(sops_dir.to_string_lossy().into_owned());
        config.sop.approval = SopApprovalConfig { groups, policies };

        let mut engine = crate::sop::SopEngine::new(config.sop.clone())
            .with_approval_broker(Arc::new(crate::sop::approval::ApprovalBroker::disabled()));
        engine.set_sops_for_test(vec![sop]);
        let action = engine
            .start_run(
                "rpc-checkpoint",
                SopEvent {
                    source: SopTriggerSource::Manual,
                    topic: None,
                    payload: None,
                    timestamp: crate::sop::engine::now_iso8601(),
                },
            )
            .unwrap();
        let run_id = match action {
            SopRunAction::CheckpointWait { run_id, .. } => run_id,
            other => panic!("expected checkpoint wait, got {other:?}"),
        };
        let engine = Arc::new(std::sync::Mutex::new(engine));
        let sessions = Arc::new(crate::rpc::session::SessionStore::new(
            16,
            Arc::new(SessionActorQueue::new(4, 10, 60)),
        ));
        let ctx = RpcContext::minimal_with_sop_engine(config, sessions, Arc::clone(&engine));
        let (tx, _rx) = tokio::sync::mpsc::channel(64);
        let mut dispatcher = RpcDispatcher::new(ctx, tx, "local:test".into());
        dispatcher.set_tui_id_for_test(Some(tui_id.to_string()));
        (dispatcher, engine, run_id, temp)
    }

    /// An RPC dispatcher over one SOP, with the driver handles under test.
    fn sops_run_dispatcher(
        sop: crate::sop::types::Sop,
        handles: Option<crate::sop::SopDriverHandles>,
    ) -> (
        RpcDispatcher,
        Arc<std::sync::Mutex<crate::sop::SopEngine>>,
        tempfile::TempDir,
    ) {
        let mut engine = crate::sop::SopEngine::new(zeroclaw_config::schema::SopConfig::default());
        engine.set_sops_for_test(vec![sop]);
        let engine = Arc::new(std::sync::Mutex::new(engine));
        let sessions = Arc::new(crate::rpc::session::SessionStore::new(
            16,
            Arc::new(zeroclaw_infra::session_queue::SessionActorQueue::new(
                4, 10, 60,
            )),
        ));
        let mem_cfg = zeroclaw_config::schema::MemoryConfig {
            backend: "sqlite".into(),
            ..zeroclaw_config::schema::MemoryConfig::default()
        };
        let temp = tempfile::tempdir().unwrap();
        let memory: Arc<dyn zeroclaw_api::memory_traits::Memory> =
            Arc::from(zeroclaw_memory::create_memory(&mem_cfg, temp.path(), None).unwrap());
        let audit = Arc::new(crate::sop::SopAuditLogger::new(memory));
        let ctx = RpcContext::minimal_with_sop_engine_and_audit(
            zeroclaw_config::schema::Config::default(),
            sessions,
            Arc::clone(&engine),
            audit,
            handles,
        );
        let (tx, _rx) = tokio::sync::mpsc::channel(64);
        (
            RpcDispatcher::new(ctx, tx, "local:test".into()),
            engine,
            temp,
        )
    }

    fn manual_sop(
        name: &str,
        deterministic: bool,
        step: crate::sop::types::SopStep,
    ) -> crate::sop::types::Sop {
        crate::sop::types::Sop {
            name: name.to_string(),
            description: "sops/run driver test".to_string(),
            version: "0.1.0".to_string(),
            priority: crate::sop::types::SopPriority::Normal,
            // A deterministic SOP runs its steps without a model turn, which is
            // what lets the driven test reach `Completed` with no provider.
            execution_mode: if deterministic {
                crate::sop::types::SopExecutionMode::Deterministic
            } else {
                crate::sop::types::SopExecutionMode::Auto
            },
            triggers: vec![crate::sop::types::SopTrigger::Manual],
            steps: vec![step],
            cooldown_secs: 0,
            max_concurrent: 4,
            location: None,
            deterministic,
            admission_policy: crate::sop::types::SopAdmissionPolicy::Parallel,
            max_pending_approvals: 0,
            agent: None,
            decision: None,
        }
    }

    async fn start_with_key(dispatcher: &RpcDispatcher, sop_name: &str, key: &str) -> String {
        dispatcher
            .handle_sops_run(&serde_json::json!({ "name": sop_name, "dedup_key": key }))
            .await
            .expect("the run starts")
            .get("run_id")
            .and_then(serde_json::Value::as_str)
            .expect("a run id comes back")
            .to_string()
    }

    /// `sops/run` drives the run it starts, like the gateway start path. A
    /// deterministic no-op step needs no model, so reaching `Completed` proves
    /// a driver really advanced the run rather than leaving it at its first
    /// step. Once terminal, the producer key no longer coalesces, so the same
    /// work item can be retried.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn sops_run_drives_the_run_it_starts() {
        let sop_name = "driven";
        let step = crate::sop::types::SopStep {
            number: 1,
            title: "No-op".to_string(),
            kind: crate::sop::types::SopStepKind::Capability,
            capability: Some("noop".to_string()),
            ..crate::sop::types::SopStep::default()
        };
        let handles = crate::sop::SopDriverHandles::default();
        let (dispatcher, engine, _temp) =
            sops_run_dispatcher(manual_sop(sop_name, true, step), Some(handles));
        let dedup_key = "ghpr_octocat/example#42";
        let run_id = start_with_key(&dispatcher, sop_name, dedup_key).await;

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        let status = loop {
            let status = engine
                .lock()
                .unwrap()
                .get_run(&run_id)
                .map(|run| run.status);
            if !matches!(
                status,
                Some(crate::sop::types::SopRunStatus::Running) | None
            ) || std::time::Instant::now() >= deadline
            {
                break status;
            }
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        };
        assert_eq!(
            status,
            Some(crate::sop::types::SopRunStatus::Completed),
            "a driver must advance the RPC-started run to a terminal state; run: {:?}",
            engine.lock().unwrap().get_run(&run_id).map(|run| (
                run.status,
                run.step_results
                    .iter()
                    .map(|r| (r.step_number, r.status, r.output.clone()))
                    .collect::<Vec<_>>()
            ))
        );
        assert_eq!(
            engine
                .lock()
                .unwrap()
                .active_dispatch_dedup_lookup(sop_name, dedup_key),
            None,
            "a terminal run must not keep suppressing a retry of the same work item"
        );
    }

    /// A shared producer key must only name a run something is advancing. When
    /// the daemon generation has already drained, the driver is refused and the
    /// run is settled, so the key must not be left pointing at it: the next Git
    /// or reconciliation producer would otherwise coalesce onto a run nothing
    /// will ever advance, and the key would suppress real work.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn sops_run_withdraws_the_producer_key_when_its_driver_is_refused() {
        let sop_name = "refused";
        let step = crate::sop::types::SopStep {
            number: 1,
            title: "Step one".to_string(),
            body: "Do the work".to_string(),
            ..crate::sop::types::SopStep::default()
        };
        let handles = crate::sop::SopDriverHandles::default();
        handles.lock().unwrap().close_and_take();
        let (dispatcher, engine, _temp) =
            sops_run_dispatcher(manual_sop(sop_name, false, step), Some(handles));
        let dedup_key = "ghpr_octocat/example#43";
        let run_id = start_with_key(&dispatcher, sop_name, dedup_key).await;

        let guard = engine.lock().unwrap();
        assert!(
            !guard.active_runs().contains_key(&run_id),
            "a run whose driver was refused is settled, not left active"
        );
        assert_eq!(
            guard.active_dispatch_dedup_lookup(sop_name, dedup_key),
            None,
            "the producer key must not point at a run nothing will advance"
        );
    }

    #[tokio::test]
    async fn sops_decide_rpc_enforces_checkpoint_membership_and_quorum() {
        use crate::sop::types::SopRunStatus;

        let (unauthorized, engine, run_id, _temp) =
            make_checkpoint_rpc_dispatcher(1, &["cli:ZeroClawOperator"], "ZeroClawAgent");
        let error = unauthorized
            .handle_sops_decide(&json!({
                "name": "rpc-checkpoint",
                "run_id": run_id.clone(),
                "decision": "approve",
            }))
            .await
            .expect_err("unauthorized RPC principal must be rejected");
        assert_eq!(error.code, AUTH_REQUIRED);
        assert_eq!(
            engine
                .lock()
                .unwrap()
                .get_run(&run_id)
                .map(|run| run.status),
            Some(SopRunStatus::PausedCheckpoint)
        );

        let (pending, engine, run_id, _temp) = make_checkpoint_rpc_dispatcher(
            2,
            &["cli:ZeroClawOperator", "cli:ZeroClawMaintainer"],
            "ZeroClawOperator",
        );
        pending
            .handle_sops_decide(&json!({
                "name": "rpc-checkpoint",
                "run_id": run_id.clone(),
                "decision": "approve",
            }))
            .await
            .expect("an authorized first vote returns the still-parked overlay");
        assert_eq!(
            engine
                .lock()
                .unwrap()
                .get_run(&run_id)
                .map(|run| run.status),
            Some(SopRunStatus::PausedCheckpoint)
        );
    }

    #[tokio::test]
    async fn sops_decide_drives_resumed_execute_step() {
        use crate::sop::{
            Sop, SopEvent, SopExecutionMode, SopPriority, SopRunAction, SopRunStatus, SopStep,
            SopStepKind, SopTrigger, SopTriggerSource,
        };
        use std::sync::{Arc, Mutex};
        use zeroclaw_config::schema::{Config, SopConfig};
        use zeroclaw_infra::session_queue::SessionActorQueue;

        let tmp = tempfile::TempDir::new().expect("temporary SOP directory");
        let sops_dir = tmp.path().join("sops");
        let sop_config = SopConfig {
            sops_dir: Some(sops_dir.to_string_lossy().into_owned()),
            ..SopConfig::default()
        };
        let config = Config {
            data_dir: tmp.path().join("data"),
            config_path: tmp.path().join("config.toml"),
            sop: sop_config.clone(),
            ..Config::default()
        };
        let sop = Sop {
            name: "rpc-resumed-execute".to_string(),
            description: "RPC resume driver regression".to_string(),
            version: "1.0.0".to_string(),
            priority: SopPriority::Normal,
            execution_mode: SopExecutionMode::Supervised,
            triggers: vec![SopTrigger::Manual],
            steps: vec![SopStep {
                number: 1,
                title: "Execute after approval".to_string(),
                kind: SopStepKind::Execute,
                ..SopStep::default()
            }],
            cooldown_secs: 0,
            max_concurrent: 1,
            location: None,
            deterministic: false,
            agent: None,
            admission_policy: crate::sop::types::SopAdmissionPolicy::Parallel,
            max_pending_approvals: 0,
            decision: None,
        };
        crate::sop::save_sop(&sops_dir, &sop).expect("save temporary SOP");

        let mut engine = crate::sop::SopEngine::new(sop_config);
        engine.reload(tmp.path());
        let engine = Arc::new(Mutex::new(engine));
        let run_id = {
            let mut guard = engine.lock().expect("engine lock");
            let action = guard
                .start_run(
                    "rpc-resumed-execute",
                    SopEvent {
                        source: SopTriggerSource::Manual,
                        topic: None,
                        payload: None,
                        timestamp: crate::sop::engine::now_iso8601(),
                    },
                )
                .expect("start approval-gated SOP");
            let SopRunAction::WaitApproval { run_id, .. } = action else {
                panic!("supervised Execute step must park for approval: {action:?}");
            };
            run_id
        };

        let queue = Arc::new(SessionActorQueue::new(4, 10, 60));
        let sessions = Arc::new(crate::rpc::session::SessionStore::new(16, queue));
        let ctx = RpcContext::minimal_with_sop_engine(config, sessions, Arc::clone(&engine));
        let (tx, _rx) = tokio::sync::mpsc::channel(64);
        let dispatcher = RpcDispatcher::new(ctx, tx, "test-peer-rpc:pid=1".to_string());

        dispatcher
            .handle_sops_decide(&serde_json::json!({
                "name": "rpc-resumed-execute",
                "run_id": run_id,
                "decision": "approve",
            }))
            .await
            .expect("RPC approval must accept the parked run");

        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            loop {
                let status = engine
                    .lock()
                    .expect("engine lock")
                    .get_run(&run_id)
                    .map(|run| run.status);
                if status == Some(SopRunStatus::Failed) {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("RPC approval must schedule the resumed ExecuteStep");

        let handles = dispatcher
            .ctx
            .sop_driver_handles
            .as_ref()
            .expect("a context holding an engine carries the generation driver set")
            .clone();
        let driver = {
            let mut guard = handles.lock().expect("driver set lock");
            assert_eq!(
                guard.len(),
                1,
                "the resumed driver must register in the generation-owned set, not detach"
            );
            // Finalize exactly as the generation drain does, so this asserts
            // against the same operation production uses.
            let mut taken = guard.close_and_take();
            taken.pop().expect("registered driver handle")
        };
        // The generation drain is a join on exactly these handles: a resumed
        // driver therefore ends inside the generation that spawned it instead
        // of running on under superseded configuration.
        driver.await.expect("the registered resumed driver joins");
    }

    #[tokio::test]
    async fn sops_decide_rejects_approval_mode_rejection() {
        use crate::sop::{
            Sop, SopEvent, SopExecutionMode, SopPriority, SopRunAction, SopRunStatus, SopStep,
            SopStepKind, SopTrigger, SopTriggerSource,
        };
        use std::sync::{Arc, Mutex};
        use zeroclaw_config::schema::{ApprovalMode, Config, SopConfig};
        use zeroclaw_infra::session_queue::SessionActorQueue;

        fn dispatcher_with_sop_engine(
            config: Config,
            engine: Arc<Mutex<crate::sop::SopEngine>>,
        ) -> RpcDispatcher {
            let queue = Arc::new(SessionActorQueue::new(4, 10, 60));
            let sessions = Arc::new(crate::rpc::session::SessionStore::new(16, queue));
            let ctx = RpcContext::minimal_with_sop_engine(config, sessions, engine);
            let (tx, _rx) = tokio::sync::mpsc::channel(64);
            let mut dispatcher = RpcDispatcher::new(ctx, tx, "test-peer-rpc:pid=1".to_string());
            dispatcher.set_tui_id_for_test(Some("alice".to_string()));
            dispatcher
        }

        let tmp = tempfile::TempDir::new().unwrap();
        let sops_dir = tmp.path().join("sops");
        let sop_config = SopConfig {
            sops_dir: Some(sops_dir.to_string_lossy().into_owned()),
            default_execution_mode: "deterministic".to_string(),
            approval_mode: ApprovalMode::AgentTool,
            ..SopConfig::default()
        };
        let config = Config {
            data_dir: tmp.path().join("data"),
            config_path: tmp.path().join("config.toml"),
            sop: sop_config.clone(),
            ..Config::default()
        };

        let sop = Sop {
            name: "rpc-agent-tool-only".to_string(),
            description: "rpc approval-mode checkpoint".to_string(),
            version: "1.0.0".to_string(),
            priority: SopPriority::Normal,
            execution_mode: SopExecutionMode::Deterministic,
            triggers: vec![SopTrigger::Manual],
            steps: vec![SopStep {
                number: 1,
                title: "Policy gate".to_string(),
                kind: SopStepKind::Checkpoint,
                ..SopStep::default()
            }],
            cooldown_secs: 0,
            max_concurrent: 1,
            location: None,
            deterministic: true,
            agent: None,
            admission_policy: crate::sop::types::SopAdmissionPolicy::Parallel,
            max_pending_approvals: 0,
            decision: None,
        };
        crate::sop::save_sop(&sops_dir, &sop).expect("save temp SOP");

        let mut engine = crate::sop::SopEngine::new(sop_config);
        engine.reload(tmp.path());
        let engine = Arc::new(Mutex::new(engine));
        let run_id = {
            let mut guard = engine.lock().expect("engine lock");
            let action = guard
                .start_run(
                    "rpc-agent-tool-only",
                    SopEvent {
                        source: SopTriggerSource::Manual,
                        topic: None,
                        payload: None,
                        timestamp: crate::sop::engine::now_iso8601(),
                    },
                )
                .expect("start approval-mode SOP");
            let SopRunAction::CheckpointWait { run_id, .. } = action else {
                panic!("approval-mode SOP must park at checkpoint, got {action:?}");
            };
            run_id
        };

        let dispatcher = dispatcher_with_sop_engine(config, Arc::clone(&engine));
        let err = dispatcher
            .handle_sops_decide(&serde_json::json!({
                "name": "rpc-agent-tool-only",
                "run_id": run_id,
                "decision": "approve",
            }))
            .await
            .expect_err("RPC principal must be rejected by approval_mode=agent_tool");
        assert_eq!(err.code, AUTH_REQUIRED);
        assert!(
            err.message.contains(&crate::i18n::get_required_cli_string(
                "sop-rpc-decision-unauthorized",
            )),
            "approval_mode rejection must surface, got: {}",
            err.message
        );
        let guard = engine.lock().expect("engine lock");
        assert_eq!(
            guard.get_run(&run_id).expect("run still active").status,
            SopRunStatus::PausedCheckpoint
        );
        assert!(
            !guard
                .run_events(&run_id)
                .unwrap_or_default()
                .iter()
                .any(|event| event.kind == "gate_resolved"),
            "rejected RPC decision must not append a gate_resolved row"
        );
    }

    #[tokio::test]
    async fn sops_decide_rejects_run_id_from_different_sop_before_broker_resolution() {
        use crate::sop::{
            Sop, SopEvent, SopExecutionMode, SopPriority, SopRunAction, SopRunStatus, SopStep,
            SopStepKind, SopTrigger, SopTriggerSource,
        };
        use std::sync::{Arc, Mutex};
        use zeroclaw_config::schema::{Config, SopConfig};
        use zeroclaw_infra::session_queue::SessionActorQueue;

        fn dispatcher_with_sop_engine(
            config: Config,
            engine: Arc<Mutex<crate::sop::SopEngine>>,
        ) -> RpcDispatcher {
            let queue = Arc::new(SessionActorQueue::new(4, 10, 60));
            let sessions = Arc::new(crate::rpc::session::SessionStore::new(16, queue));
            let ctx = RpcContext::minimal_with_sop_engine(config, sessions, engine);
            let (tx, _rx) = tokio::sync::mpsc::channel(64);
            let mut dispatcher = RpcDispatcher::new(ctx, tx, "test-peer-rpc:pid=1".to_string());
            dispatcher.set_tui_id_for_test(Some("alice".to_string()));
            dispatcher
        }

        fn checkpoint_sop(name: &str) -> Sop {
            Sop {
                name: name.to_string(),
                description: format!("{name} checkpoint"),
                version: "1.0.0".to_string(),
                priority: SopPriority::Normal,
                execution_mode: SopExecutionMode::Deterministic,
                triggers: vec![SopTrigger::Manual],
                steps: vec![SopStep {
                    number: 1,
                    title: "Gate".to_string(),
                    kind: SopStepKind::Checkpoint,
                    ..SopStep::default()
                }],
                cooldown_secs: 0,
                max_concurrent: 1,
                location: None,
                deterministic: true,
                agent: None,
                admission_policy: crate::sop::types::SopAdmissionPolicy::Parallel,
                max_pending_approvals: 0,
                decision: None,
            }
        }

        let tmp = tempfile::TempDir::new().unwrap();
        let sops_dir = tmp.path().join("sops");
        let sop_config = SopConfig {
            sops_dir: Some(sops_dir.to_string_lossy().into_owned()),
            default_execution_mode: "deterministic".to_string(),
            ..SopConfig::default()
        };
        let config = Config {
            data_dir: tmp.path().join("data"),
            config_path: tmp.path().join("config.toml"),
            sop: sop_config.clone(),
            ..Config::default()
        };

        crate::sop::save_sop(&sops_dir, &checkpoint_sop("rpc-a")).expect("save rpc-a");
        crate::sop::save_sop(&sops_dir, &checkpoint_sop("rpc-b")).expect("save rpc-b");

        let mut engine = crate::sop::SopEngine::new(sop_config);
        engine.reload(tmp.path());
        assert_eq!(engine.sops().len(), 2, "both temp SOPs should load");
        let engine = Arc::new(Mutex::new(engine));

        let run_id = {
            let mut guard = engine.lock().expect("engine lock");
            let action = guard
                .start_run(
                    "rpc-b",
                    SopEvent {
                        source: SopTriggerSource::Manual,
                        topic: None,
                        payload: None,
                        timestamp: crate::sop::engine::now_iso8601(),
                    },
                )
                .expect("start rpc-b SOP");
            let SopRunAction::CheckpointWait { run_id, .. } = action else {
                panic!("rpc-b must park at checkpoint, got {action:?}");
            };
            run_id
        };

        let dispatcher = dispatcher_with_sop_engine(config, Arc::clone(&engine));
        let err = dispatcher
            .handle_sops_decide(&serde_json::json!({
                "name": "rpc-a",
                "run_id": run_id,
                "decision": "approve",
            }))
            .await
            .expect_err("mismatched name/run_id must be rejected before broker resolution");
        assert_eq!(err.code, INVALID_PARAMS);
        assert!(
            err.message.contains("belongs to SOP 'rpc-b', not 'rpc-a'"),
            "mismatch rejection must name both SOPs, got: {}",
            err.message
        );

        let guard = engine.lock().expect("engine lock");
        let run = guard.get_run(&run_id).expect("rpc-b run still active");
        assert_eq!(run.sop_name, "rpc-b");
        assert_eq!(run.status, SopRunStatus::PausedCheckpoint);
        assert!(
            !guard
                .run_events(&run_id)
                .unwrap_or_default()
                .iter()
                .any(|event| event.kind == "gate_resolved"),
            "mismatched RPC decision must not append a gate_resolved row"
        );
    }

    #[test]
